            self.text = raw.decode("utf-8")
        except UnicodeDecodeError as e:
            raise AdmissionError("MALFORMED_UTF8", str(e)) from e
        if self.text.startswith("\ufeff"):
            raise AdmissionError("BOM_FORBIDDEN", "BOM")
