    def rec(self, layer: str, name: str, ok: bool, detail: str = "", *, refuse: bool = True):
        item = {"layer": layer, "name": name, "ok": bool(ok), "detail": detail}
        self.joins.append(item)
        if not ok and self.first_refusal is None and refuse:
