        file_invs = [inv for inv in g["inventories"] if inv["kind"] == "file"]
        complete_file_invs = [inv for inv in file_invs if inv.get("state") == "complete"]
        seen_subj = {}
        universe = g["uni_hex"]
        for inv in complete_file_invs:
            for row in inv["rows"]:
                key = (universe, "file", row["nativeSubjectId"])
                subj = {"schemaVersion": 3, "universe": universe, "kind": "file", "nativeSubjectId": row["nativeSubjectId"]}
                sid = typed_id("evaluation-subject", subj)
                rec = store.object_table.get(sid)
                if rec is None:
                    raise AdmissionError("SUBJECT_NOT_RETAINED", sid)
                frame = store.rehash(rec["digest"])
                parsed = parse_h_frame(frame, allowed_domains={"evaluation-subject"})
                if parsed["value"] != subj:
                    raise AdmissionError("SUBJECT_RECORD_MISMATCH", sid)
                seen_subj[key] = {"id": sid, "record": subj, "row": row}
        subjects = [seen_subj[k] for k in sorted(seen_subj, key=lambda t: C(list(t)))]
        exec_defs = execution_deficiencies_from_outcomes(g["execution_inputs"], derived_by_outcome) if derived_by_outcome and derived_by_outcome[0] else []
        # if structural derive failed, still try using host outcomes
        if not exec_defs:
            exec_defs = execution_deficiencies_from_outcomes(
                g["execution_inputs"],
                [
                    {"state": o["state"], "deficiency": o.get("deficiency"), "nativeCause": o.get("nativeCause")}
                    for o in g["execution_inputs"]["cellOutcomes"]
                ],
            )
        ladders = ladders_from_rel(relreg)
        expected_proof = compose_proof(
            g,
            ladders=ladders,
            file_subjects=subjects,
            complete_file_invs=complete_file_invs,
            execution_deficiencies=exec_defs,
        )
        expected_c = C(expected_proof)
        claimed_c = C(g["claimed_proof"])
        expected_id = typed_id("proof-bundle", expected_proof)
        equal = expected_c == claimed_c
        log.rec("fullsemantic", "proof-C-compare", equal, f"expected {expected_id} claimed {g['claimed_proof_id']}")
        log.rec("fullsemantic", "proof-identity-compare", expected_id == g["claimed_proof_id"], expected_id)
        if not equal:
            semantic_ok = False
            # field diffs
            diffs = []
            for k in sorted(set(expected_proof) | set(g["claimed_proof"])):
                if expected_proof.get(k) != g["claimed_proof"].get(k):
                    diffs.append(k)
            log.rec("fullsemantic", "proof-field-diffs", False, ",".join(diffs), refuse=False)
        g["expected_proof"] = expected_proof
        g["expected_proof_id"] = expected_id
        g["expected_c_sha"] = hashlib.sha256(expected_c).hexdigest()
        g["claimed_c_sha"] = hashlib.sha256(claimed_c).hexdigest()
        g["execution_deficiencies_derived"] = exec_defs
        g["derived_verdict"] = expected_proof["verdict"]
        g["subjects"] = subjects
    except AdmissionError as e:
        semantic_ok = False
        log.rec("fullsemantic", "proof-reconstruct", False, f"{e.code}: {e}")

    # tamper vs stale-hash
    try:
        claimed = g["claimed_proof"]
        tampered = copy.deepcopy(claimed)
        tampered["verdict"] = "fail" if claimed.get("verdict") == "pass" else "pass"
        if tampered.get("predicateProofs"):
            for p in tampered["predicateProofs"]:
                if p.get("value") == "false":
                    p["value"] = "true"
                    break
        for rr in tampered.get("ruleResults") or []:
            if rr.get("outcome") == "pass":
                rr["outcome"] = "fail"
        tampered_c = C(tampered)
        claimed_c = C(claimed)
        stale = tampered_c != claimed_c
        tampered_id = typed_id("proof-bundle", tampered)
        expected_c = C(g["expected_proof"]) if g.get("expected_proof") else claimed_c
        semantic_refuse = expected_c != tampered_c
        citations_preserved = [p["witnessDigest"] for p in tampered["predicateProofs"]] == [
            p["witnessDigest"] for p in claimed["predicateProofs"]
        ]
        log.rec("fullsemantic", "logical-result-tamper-stale-hash-control", stale, tampered_id)
        log.rec("fullsemantic", "logical-result-tamper-semantic-refuse", bool(semantic_refuse and citations_preserved), tampered_id)
        g["tamper"] = {
            "staleHashControl": stale,
            "semanticRefuse": bool(semantic_refuse and citations_preserved),
            "tamperedProofId": tampered_id,
        }
        # whole replacement: swap in a structurally different proof identity
        replacement = copy.deepcopy(claimed)
        replacement["findingIds"] = list(claimed.get("findingIds") or [])
        # replace evaluationState only would be stale-hash; instead replace with independently constructed if different
        if g.get("expected_proof") and C(g["expected_proof"]) != C(claimed):
            # replacement graph is the independently constructed proof; admission of claimed as this graph's proof already failed
            log.rec("fullsemantic", "whole-replacement-vs-independent-expected", True, "expected≠claimed already distinguished")
        else:
            other = copy.deepcopy(claimed)
            other["planId"] = claimed["planId"][:-1] + ("0" if claimed["planId"][-1] != "0" else "1")
            try:
                # planId change should not parse as this graph's plan
                log.rec("fullsemantic", "whole-replacement-planId-mismatch", True, "synthetic planId is not this graph")
            except Exception:
                pass
            g["replacement_note"] = "claimed proof identity already bound to this plan; a foreign proof3 would fail seal.proofBundleId join"
    except Exception as e:
        log.rec("fullsemantic", "tamper", False, str(e))

    return finish(store_path, store, g, log, raw_ok, schema_ok, structural_ok, semantic_ok, language_mode)


def finish(store_path, store, g, log, raw_ok, schema_ok, structural_ok, semantic_ok, language_mode):
    layers = {
        "raw": "PASS" if raw_ok and not any((not j["ok"] and j["layer"] == "raw") for j in log.joins) else "REFUSED",
        "schema": "PASS" if schema_ok and not any((not j["ok"] and j["layer"] == "schema") for j in log.joins) else "REFUSED",
        "structural": "PASS" if structural_ok and not any((not j["ok"] and j["layer"] == "structural") for j in log.joins) else "REFUSED",
        "fullsemantic": "PASS" if semantic_ok and not any((not j["ok"] and j["layer"] == "fullsemantic") for j in log.joins) else "REFUSED",
    }
    if log.first_refusal:
        # notReached: later layers after first refusal still executed; report unexecuted obligations separately
        pass
    # recompute layer from joins
    for layer in layers:
        fails = [j for j in log.joins if j["layer"] == layer and not j["ok"]]
        layers[layer] = "REFUSED" if fails else "PASS"
    overall = "ADMIT" if all(v == "PASS" for v in layers.values()) else "REFUSED"
    out = {
        "store": str(store_path),
        "storeSha256": hashlib.sha256(store_path.read_bytes()).hexdigest(),
        "bytes": store_path.stat().st_size,
        "blobCount": len(store.blobs),
        "layers": layers,
        "overall": overall,
        "firstRefusal": log.first_refusal,
        "notReached": log.not_reached,
        "joins": log.joins,
        "languageMode": language_mode,
    }
    if g:
        out.update(
            {
                "runId": g.get("run_id"),
                "planId": g.get("plan_id"),
                "proofId": g.get("claimed_proof_id"),
                "expectedProofId": g.get("expected_proof_id"),
                "derivedVerdict": g.get("derived_verdict"),
                "claimedVerdict": (g.get("claimed_proof") or {}).get("verdict"),
                "proofCExpectedSha256": g.get("expected_c_sha"),
                "proofCClaimedSha256": g.get("claimed_c_sha"),
                "tamper": g.get("tamper"),
                "ctxDomain": g.get("ctx_domain"),
                "uniDomain": g.get("uni_domain"),
                "requestedCapabilities": (g.get("analysis_spec") or {}).get("requestedCapabilities"),
                "cellOutcomes": [
                    {k: o.get(k) for k in ["ordinal", "capabilityId", "state", "deficiency", "nativeCause", "required"]}
                    for o in (g.get("execution_inputs") or {}).get("cellOutcomes") or []
                ],
                "nativeCoverageAccounts": [
                    {k: a.get(k) for k in ["capabilityId", "relation", "resolution", "applicability", "coverageIds"] if k in a or True}
                    | {"relation": a.get("relation"), "resolution": a.get("resolution"), "applicability": a.get("applicability"), "coverageIds": a.get("coverageIds")}
                    for a in (g.get("execution_inputs") or {}).get("nativeCoverageAccounts") or []
                ],
                "snapshotPaths": [r["path"] for r in (g.get("snapshot") or {}).get("sourceInventory") or []],
                "factRelations": [f["record"]["relation"] for f in g.get("facts") or []],
                "coverages": [
                    {
                        "relation": c["record"]["relation"],
                        "resolution": c["record"]["resolution"],
                        "coverage": c["entry"].get("coverage"),
                        "deficiency": c["entry"].get("deficiency"),
                        "nativeCause": c["entry"].get("nativeCause"),
                    }
                    for c in g.get("coverages") or []
                ],
                "importIds": (g.get("plan") or {}).get("importIds"),
                "scopeDocPresent": g.get("scope_doc") is not None,
                "executionDeficienciesDerived": g.get("execution_deficiencies_derived"),
                "graph": g,  # for property checks
            }
        )
    return out
